SELECT s.id, s.student_no, s.course_id, c.course_name, c.credit, s.score
FROM score s
JOIN course c ON c.course_id = s.course_id
WHERE s.student_no = #{studentNo}

    AND s.course_id = #{courseId}


    AND s.score >= #{minScore}

ORDER BY s.course_id

SELECT id, student_no, course_id, score
FROM score
WHERE id = #{id}

SELECT COUNT(*)
FROM score
WHERE student_no = #{studentNo}
  AND course_id = #{courseId}

mapper.update:
UPDATE score
SET score = #{score}
WHERE id = #{id}
